function makeModel(id,title,s){const r=run(s);return {id,title,kind:'byte-memory',invariant:'Every displayed byte belongs to a fixed array slot. Green NUL cells are zero bytes; the first zero defines each string view. Counters exclude preflight validation scans.',spec:s,result:r.result,frames:r.frames.map((f,i)=>{const prev=i?r.frames[i-1].snapshot:null;f.teaching.currentState=clone(f.snapshot);f.teaching.changes=prev?Object.keys(f.snapshot).filter(k=>JSON.stringify(prev[k])!==JSON.stringify(f.snapshot[k])).map(k=>({field:k,before:prev[k],after:f.snapshot[k]})):[];for(const head of [f.snapshot.read,f.snapshot.write])if(head)f.teaching.checks.push({expression:head.row+' byte index '+head.index+' is inside its '+f.snapshot[head.row].length+'-byte object; displayed value is '+f.snapshot[head.row][head.index]+'.',result:'verified'});return {...f,svg:svg(f)};})};}
